from sqlalchemy import MetaData, Table, Column, String, Integer, BigInteger, JSON, ForeignKey, CheckConstraint
metadata = MetaData()
state = Table('crm_state', metadata, Column('id', Integer, primary_key=True), Column('rev', Integer, nullable=False), Column('payload', JSON, nullable=False), CheckConstraint('id = 1'), CheckConstraint('rev >= 0'))
clients = Table('crm_clients', metadata, Column('id', String(200), primary_key=True), Column('position', Integer, nullable=False), Column('version', Integer, nullable=False), Column('payload', JSON, nullable=False), CheckConstraint('version >= 0'))
users = Table('crm_users', metadata, Column('id', String(100), primary_key=True), Column('role', String(20), nullable=False), Column('active', Integer, nullable=False, server_default='1'), Column('must_change_password', Integer, nullable=False, server_default='0'), Column('last_login', BigInteger), Column('created', BigInteger), CheckConstraint("role in ('admin', 'sales', 'design', 'measurement', 'accounts', 'reader', 'assigned')", name='crm_users_role_check'), CheckConstraint('active in (0,1)'), CheckConstraint('must_change_password in (0,1)', name='crm_users_must_change_check'))
grants = Table('crm_client_grants', metadata, Column('user_id', String(100), ForeignKey('crm_users.id'), primary_key=True), Column('client_id', String(200), ForeignKey('crm_clients.id'), primary_key=True, index=True), Column('can_write', Integer, nullable=False, server_default='0'), CheckConstraint('can_write in (0,1)'))
# expires is the idle expiry; it never passes created + the absolute maximum (migration 0007).
sessions = Table('crm_sessions', metadata, Column('hash', String(64), primary_key=True), Column('user_id', String(100), ForeignKey('crm_users.id'), nullable=False, index=True), Column('expires', BigInteger, nullable=False, index=True), Column('created', BigInteger, nullable=False), Column('last_seen', BigInteger, nullable=False))
audit = Table('crm_audit', metadata, Column('id', String(36), primary_key=True), Column('user_id', String(100), nullable=False), Column('action', String(80), nullable=False), Column('resource', String(200)), Column('created', BigInteger, nullable=False))

credentials = Table('crm_credentials', metadata, Column('user_id', String(100), ForeignKey('crm_users.id'), primary_key=True), Column('email', String(320), nullable=False, unique=True), Column('password_hash', String(300), nullable=False))

# Separate binding tables keep the unmigrated local login schema compatible.
auth_accounts = Table('crm_auth_accounts', metadata, Column('user_id', String(100), ForeignKey('crm_users.id'), primary_key=True), Column('realm', String(36), nullable=False))
auth_sessions = Table('crm_auth_sessions', metadata, Column('hash', String(64), ForeignKey('crm_sessions.hash', ondelete='CASCADE'), primary_key=True), Column('realm', String(36), nullable=False))

recovery_emails = Table('crm_recovery_emails', metadata, Column('user_id', String(100), ForeignKey('crm_users.id'), primary_key=True), Column('email', String(320), nullable=False))
password_resets = Table('crm_password_resets', metadata, Column('hash', String(64), primary_key=True), Column('user_id', String(100), ForeignKey('crm_users.id'), nullable=False, index=True), Column('realm', String(36), nullable=False), Column('expires', BigInteger, nullable=False), Column('password_fingerprint', String(64), nullable=False))

mfa_factors = Table('crm_mfa', metadata, Column('user_id', String(100), ForeignKey('crm_users.id'), primary_key=True), Column('secret', String(500), nullable=False), Column('enabled', Integer, nullable=False), Column('expires', BigInteger, nullable=False), Column('last_counter', BigInteger, nullable=False))
mfa_codes = Table('crm_mfa_codes', metadata, Column('hash', String(64), primary_key=True), Column('user_id', String(100), ForeignKey('crm_users.id'), nullable=False, index=True))
# Sign-in codes sent by email (migration 0010): hashed challenge cookie, hashed code bound to it.
login_codes = Table('crm_login_codes', metadata, Column('hash', String(64), primary_key=True), Column('user_id', String(100), ForeignKey('crm_users.id'), nullable=False, index=True), Column('realm', String(36), nullable=False), Column('code_hash', String(64), nullable=False), Column('password_fingerprint', String(64), nullable=False), Column('expires', BigInteger, nullable=False), Column('attempts', Integer, nullable=False), Column('sends', Integer, nullable=False))
mfa_challenges = Table('crm_mfa_challenges', metadata, Column('hash', String(64), primary_key=True), Column('user_id', String(100), ForeignKey('crm_users.id'), nullable=False, index=True), Column('realm', String(36), nullable=False), Column('password_fingerprint', String(64), nullable=False), Column('factor_fingerprint', String(64), nullable=False), Column('expires', BigInteger, nullable=False), Column('attempts', Integer, nullable=False))
